# Expected values are SymPy's str() outputs for the same calls, with ** shown
# as ^ (sympy/polys/matrices/tests, test_fields.py, test_rings.py,
# test_polytools.py, sympy/polys/series/tests, test_polyroots.py, test_polyfuncs.py,
# test_groebnertools.py, test_rootoftools.py).

skip_unless_full_tests()

skip_on_cran()

pt_env <- function() {
  e <- new.env(parent = environment(Symbol))
  for (s in c("a", "b", "c", "d", "t", "w", "x", "y", "z")) assign(s, Symbol(s), envir = e)
  el <- function(K, s) .de_convert(K, sympify(s))
  e$.dmt <- function(K, rows, shape, fmt = NULL) {
    M <- DomainMatrix(lapply(rows, function(r) lapply(r, function(s) el(K, s))), shape, K)
    if (identical(fmt, "sparse")) M <- M$to_sparse()
    M
  }
  e$.dms <- function(K, dod, shape) DomainMatrix(lapply(dod, function(r) lapply(r, function(s) el(K, s))), shape, K)
  e$.withF <- function(s, K, f) do.call(f, unname(field(s, K)))
  e$.withR <- function(s, K, f) do.call(f, unname(ring(s, K)))
  e
}
pt_run <- function(code) {
  v <- tryCatch(eval(parse(text = code), envir = pt_env()), error = function(e) e)
  if (inherits(v, "error")) {
    cl <- setdiff(class(v), c("simpleError", "error", "condition", "sympy_error"))
    return(paste0("ERR ", if (length(cl)) cl[[1L]] else "error", ": ", gsub("\n", "\\n", conditionMessage(v), fixed = TRUE)))
  }
  s <- if (is_sym(v)) sstr(v) else gsub("**", "^", .dmpy_str(v), fixed = TRUE)
  gsub("\n", "\\n", s, fixed = TRUE)
}
pt_check <- function(cases) for (i in seq_along(cases)) expect_identical(pt_run(cases[[i]][1L]), cases[[i]][2L], label = cases[[i]][1L])

test_that("DomainMatrix, DDM, SDM and normal forms match SymPy (part 1)", {
