    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\")), c(1, 3))$rref(method = 'GJ')",
      "(DomainMatrix([[1, 2, 3]], (1, 3), QQ), (0,))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\")), c(1, 3))$rref(method = 'FF')",
