test_that("DomainMatrix, DDM, SDM and normal forms match SymPy (part 3)", {
  pt_check(list(
    c(".dmt(ZZ, list(list(\"0\", \"0\", \"0\"), list(\"0\", \"0\", \"0\"), list(\"0\", \"0\", \"0\")), c(3, 3))$to_Matrix()",
      "Matrix([[0, 0, 0], [0, 0, 0], [0, 0, 0]])"),
    c(".dmt(ZZ, list(list(\"0\", \"0\", \"0\"), list(\"0\", \"0\", \"0\"), list(\"0\", \"0\", \"0\")), c(3, 3))$nnz()",
      "0"),
    c(".dmt(ZZ, list(list(\"0\", \"0\", \"0\"), list(\"0\", \"0\", \"0\"), list(\"0\", \"0\", \"0\")), c(3, 3))$fflu()",
      "(DomainMatrix([[1, 0, 0], [0, 1, 0], [0, 0, 1]], (3, 3), ZZ), DomainMatrix([[1, 0, 0], [0, 1, 0], [0, 0, 1]], (3, 3), ZZ), DomainMatrix([[1, 0, 0], [0, 1, 0], [0, 0, 1]], (3, 3), ZZ), DomainMatrix([[0, 0, 0], [0, 0, 0], [0, 0, 0]], (3, 3), ZZ))"),
