    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3)) * .dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$transpose()",
      "DomainMatrix([[8, 4, 0], [4, 8, 4], [0, 4, 4]], (3, 3), ZZ)"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$rref(method = 'CD')",
      "(DomainMatrix([[1, 0, 0], [0, 1, 0], [0, 0, 1]], (3, 3), QQ), (0, 1, 2))"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$rref_den(method = 'CD')",
