      "(1, DomainMatrix([[2, 2, 0], [0, 2, 2], [0, 0, 2]], (3, 3), QQ))"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$det()",
      "8"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$to_sparse()$det()",
      "8"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$charpoly()",
      "[1, -6, 12, -8]"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$rep$charpoly()",
      "[1, -6, 12, -8]"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$to_sdm()$charpoly()",
      "[1, -6, 12, -8]"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$to_field()$inv()",
      "DomainMatrix([[1/2, -1/2, 1/2], [0, 1/2, -1/2], [0, 0, 1/2]], (3, 3), QQ)"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$inv_den()",
      "(DomainMatrix([[1, -1, 1], [0, 1, -1], [0, 0, 1]], (3, 3), ZZ), 2)"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$adj_det()",
      "(DomainMatrix([[4, -4, 4], [0, 4, -4], [0, 0, 4]], (3, 3), ZZ), 8)"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))^2",
      "DomainMatrix([[4, 8, 4], [0, 4, 8], [0, 0, 4]], (3, 3), ZZ)"),
    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$scc()",
