    c(".dmt(ZZ, list(list(\"2\", \"2\", \"0\"), list(\"0\", \"2\", \"2\"), list(\"0\", \"0\", \"2\")), c(3, 3))$charpoly_factor_blocks()",
      "[([1, -2], 3)]")
