      "DomainMatrix([[3, 1], [4, 2], [1, 1]], (3, 2), QQ)"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$to_Matrix()",
      "Matrix([[3, 4, 1], [1, 2, 1]])"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$nnz()",
      "6"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$fflu()",
      "(DomainMatrix([[1, 0], [0, 1]], (2, 2), QQ), DomainMatrix([[3, 0], [1, 2]], (2, 2), QQ), DomainMatrix([[3, 0], [0, 6]], (2, 2), QQ), DomainMatrix([[3, 4, 1], [0, 2, 2]], (2, 3), QQ))"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3)) * .dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$transpose()",
      "DomainMatrix([[26, 12], [12, 6]], (2, 2), QQ)"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$rref(method = 'CD')",
      "(DomainMatrix([[1, 0, -1], [0, 1, 1]], (2, 3), QQ), (0, 1))"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$rref_den(method = 'CD')",
      "(DomainMatrix([[1, 0, -1], [0, 1, 1]], (2, 3), QQ), MPQ(1,1), (0, 1))"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$to_field()$nullspace(divide_last = TRUE)",
      "DomainMatrix([[1, -1, 1]], (1, 3), QQ)"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$to_field()$columnspace()",
      "DomainMatrix([[3, 4], [1, 2]], (2, 2), QQ)"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$to_field()$rowspace()",
      "DomainMatrix([[3, 4, 1], [1, 2, 1]], (2, 3), QQ)"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$content()",
      "1"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$primitive()",
      "(MPQ(1,1), DomainMatrix([[3, 4, 1], [1, 2, 1]], (2, 3), QQ))"),
    c(".dmt(QQ, list(list(\"3\", \"4\", \"1\"), list(\"1\", \"2\", \"1\")), c(2, 3))$to_field()$clear_denoms()",
      "(1, DomainMatrix([[3, 4, 1], [1, 2, 1]], (2, 3), QQ))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))",
      "DomainMatrix([[1, 0], [1, 3], [0, 1]], (3, 2), QQ)"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$rref()",
      "(DomainMatrix([[1, 0], [0, 1], [0, 0]], (3, 2), QQ), (0, 1))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$rref_den()",
      "(DomainMatrix([[1, 0], [0, 1], [0, 0]], (3, 2), QQ), MPQ(1,1), (0, 1))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$to_sparse()$rref()",
      "(DomainMatrix({0: {0: 1}, 1: {1: 1}}, (3, 2), QQ), (0, 1))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$to_sparse()$rref_den()",
      "(DomainMatrix({0: {0: 1}, 1: {1: 1}}, (3, 2), QQ), MPQ(1,1), (0, 1))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$rref(method = 'GJ')",
      "(DomainMatrix([[1, 0], [0, 1], [0, 0]], (3, 2), QQ), (0, 1))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$rref(method = 'FF')",
      "(DomainMatrix([[1, 0], [0, 1], [0, 0]], (3, 2), QQ), (0, 1))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$rref_den(method = 'GJ')",
      "(DomainMatrix([[1, 0], [0, 1], [0, 0]], (3, 2), QQ), MPQ(1,1), (0, 1))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$rref_den(method = 'FF_dense')",
      "(DomainMatrix([[3, 0], [0, 3], [0, 0]], (3, 2), QQ), MPQ(3,1), (0, 1))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$rref(method = 'GJ_dense')",
      "(DomainMatrix([[1, 0], [0, 1], [0, 0]], (3, 2), QQ), (0, 1))"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$rank()",
      "2"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$nullspace()",
      "DomainMatrix([], (0, 2), QQ)"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$to_sparse()$nullspace()",
      "DomainMatrix({}, (0, 2), QQ)"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$rep$rref_den()",
      "(DDM([[MPQ(3,1), MPQ(0,1)], [MPQ(0,1), MPQ(3,1)], [MPQ(0,1), MPQ(0,1)]], (3, 2), QQ), MPQ(3,1), [0, 1])"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$to_sdm()$rref_den()",
      "(SDM({0: {0: MPQ(3,1)}, 1: {1: MPQ(3,1)}}, (3, 2), QQ), MPQ(3,1), [0, 1])"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$to_field()$to_sdm()$rref()",
      "(SDM({0: {0: MPQ(1,1)}, 1: {1: MPQ(1,1)}}, (3, 2), QQ), [0, 1])")
  ))
})

test_that("DomainMatrix, DDM, SDM and normal forms match SymPy (part 8)", {
  pt_check(list(
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$to_field()$rep$rref()",
      "(DDM([[MPQ(1,1), MPQ(0,1)], [MPQ(0,1), MPQ(1,1)], [MPQ(0,1), MPQ(0,1)]], (3, 2), QQ), [0, 1])"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$transpose()",
      "DomainMatrix([[1, 1, 0], [0, 3, 1]], (2, 3), QQ)"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$to_Matrix()",
      "Matrix([[1, 0], [1, 3], [0, 1]])"),
    c(".dmt(QQ, list(list(\"1\", \"0\"), list(\"1\", \"3\"), list(\"0\", \"1\")), c(3, 2))$nnz()",
      "4"),
