    c(".dmt(QQ, list(list(\"0\", \"1\"), list(\"0\", \"2\"), list(\"1\", \"0\")), c(3, 2))$primitive()",
      "(MPQ(1,1), DomainMatrix([[0, 1], [0, 2], [1, 0]], (3, 2), QQ))"),
    c(".dmt(QQ, list(list(\"0\", \"1\"), list(\"0\", \"2\"), list(\"1\", \"0\")), c(3, 2))$to_field()$clear_denoms()",
      "(1, DomainMatrix([[0, 1], [0, 2], [1, 0]], (3, 2), QQ))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))",
      "DomainMatrix([[I, 1, 1], [1, 1, 1]], (2, 3), ZZ_I)"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$rref()",
      "(DomainMatrix([[1, 0, 0], [0, 1, 1]], (2, 3), QQ_I), (0, 1))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$rref_den()",
      "(DomainMatrix([[-1 + I, 0, 0], [0, -1 + I, -1 + I]], (2, 3), ZZ_I), ZZ_I(-1, 1), (0, 1))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$to_sparse()$rref()",
      "(DomainMatrix({0: {0: 1}, 1: {1: 1, 2: 1}}, (2, 3), QQ_I), (0, 1))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$to_sparse()$rref_den()",
      "(DomainMatrix({0: {0: -1 + I}, 1: {2: -1 + I, 1: -1 + I}}, (2, 3), ZZ_I), ZZ_I(-1, 1), (0, 1))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$rref(method = 'GJ')",
      "(DomainMatrix([[1, 0, 0], [0, 1, 1]], (2, 3), QQ_I), (0, 1))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$rref(method = 'FF')",
      "(DomainMatrix([[1, 0, 0], [0, 1, 1]], (2, 3), QQ_I), (0, 1))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$rref_den(method = 'GJ')",
      "(DomainMatrix([[1, 0, 0], [0, 1, 1]], (2, 3), ZZ_I), ZZ_I(1, 0), (0, 1))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$rref_den(method = 'FF_dense')",
      "(DomainMatrix([[-1 + I, 0, 0], [0, -1 + I, -1 + I]], (2, 3), ZZ_I), ZZ_I(-1, 1), (0, 1))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$rref(method = 'GJ_dense')",
      "(DomainMatrix([[1, 0, 0], [0, 1, 1]], (2, 3), QQ_I), (0, 1))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$rank()",
      "2"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$nullspace()",
      "DomainMatrix([[0, -1 - I, 1 + I]], (1, 3), ZZ_I)"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$to_sparse()$nullspace()",
      "DomainMatrix({0: {2: 1 + I, 1: -1 - I}}, (1, 3), ZZ_I)"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$rep$rref_den()",
      "(DDM([[ZZ_I(-1, 1), ZZ_I(0, 0), ZZ_I(0, 0)], [ZZ_I(0, 0), ZZ_I(-1, 1), ZZ_I(-1, 1)]], (2, 3), ZZ_I), ZZ_I(-1, 1), [0, 1])"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$to_sdm()$rref_den()",
      "(SDM({0: {0: ZZ_I(-1, 1)}, 1: {2: ZZ_I(-1, 1), 1: ZZ_I(-1, 1)}}, (2, 3), ZZ_I), ZZ_I(-1, 1), [0, 1])"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$to_field()$to_sdm()$rref()",
      "(SDM({0: {0: QQ_I(1, 0)}, 1: {1: QQ_I(1, 0), 2: QQ_I(1, 0)}}, (2, 3), QQ_I), [0, 1])"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$to_field()$rep$rref()",
      "(DDM([[QQ_I(1, 0), QQ_I(0, 0), QQ_I(0, 0)], [QQ_I(0, 0), QQ_I(1, 0), QQ_I(1, 0)]], (2, 3), QQ_I), [0, 1])"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$transpose()",
      "DomainMatrix([[I, 1], [1, 1], [1, 1]], (3, 2), ZZ_I)"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$to_Matrix()",
      "Matrix([[I, 1, 1], [1, 1, 1]])"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$nnz()",
      "6"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$fflu()",
      "(DomainMatrix([[1, 0], [0, 1]], (2, 2), ZZ_I), DomainMatrix([[I, 0], [1, -1 + I]], (2, 2), ZZ_I), DomainMatrix([[I, 0], [0, -1 - I]], (2, 2), ZZ_I), DomainMatrix([[I, 1, 1], [0, -1 + I, -1 + I]], (2, 3), ZZ_I))"),
    c(".dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3)) * .dmt(ZZ_I, list(list(\"I\", \"1\", \"1\"), list(\"1\", \"1\", \"1\")), c(2, 3))$transpose()",
      "DomainMatrix([[1, 2 + I], [2 + I, 3]], (2, 2), ZZ_I)"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))",
      "DomainMatrix([[EX(a), EX(b), EX(1)], [EX(c), EX(d), EX(1)]], (2, 3), EX)"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$rref()",
      "(DomainMatrix([[EX(1), EX(0), EX(-b/(a*d - b*c) + d/(a*d - b*c))], [EX(0), EX(1), EX(a/(a*d - b*c) - c/(a*d - b*c))]], (2, 3), EX), (0, 1))"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$rref_den()",
      "(DomainMatrix([[EX(a*d - b*c), EX(0), EX(-b + d)], [EX(0), EX(a*d - b*c), EX(a - c)]], (2, 3), EX), EX(a*d - b*c), (0, 1))"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$to_sparse()$rref()",
      "(DomainMatrix({0: {0: EX(1), 2: EX(-b/(a*d - b*c) + d/(a*d - b*c))}, 1: {1: EX(1), 2: EX(a/(a*d - b*c) - c/(a*d - b*c))}}, (2, 3), EX), (0, 1))")
  ))
})

test_that("DomainMatrix, DDM, SDM and normal forms match SymPy (part 9)", {
  pt_check(list(
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$to_sparse()$rref_den()",
      "(DomainMatrix({0: {2: EX(-b + d), 0: EX(a*d - b*c)}, 1: {2: EX(a - c), 1: EX(a*d - b*c)}}, (2, 3), EX), EX(a*d - b*c), (0, 1))"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$rref(method = 'GJ')",
      "(DomainMatrix([[EX(1), EX(0), EX(-b/(a*d - b*c) + d/(a*d - b*c))], [EX(0), EX(1), EX(a/(a*d - b*c) - c/(a*d - b*c))]], (2, 3), EX), (0, 1))"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$rref(method = 'FF')",
      "(DomainMatrix([[EX(1), EX(0), EX(-b/(a*d - b*c) + d/(a*d - b*c))], [EX(0), EX(1), EX(a/(a*d - b*c) - c/(a*d - b*c))]], (2, 3), EX), (0, 1))"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$rref_den(method = 'GJ')",
      "(DomainMatrix([[EX(1), EX(0), EX(-b/(a*d - b*c) + d/(a*d - b*c))], [EX(0), EX(1), EX(a/(a*d - b*c) - c/(a*d - b*c))]], (2, 3), EX), EX(1), (0, 1))"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$rref_den(method = 'FF_dense')",
      "(DomainMatrix([[EX(a*d - b*c), EX(0), EX(-b + d)], [EX(0), EX(a*d - b*c), EX(a - c)]], (2, 3), EX), EX(a*d - b*c), (0, 1))"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$rref(method = 'GJ_dense')",
      "(DomainMatrix([[EX(1), EX(0), EX(-b/(a*d - b*c) + d/(a*d - b*c))], [EX(0), EX(1), EX(a/(a*d - b*c) - c/(a*d - b*c))]], (2, 3), EX), (0, 1))"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$rank()",
      "2"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$nullspace()",
      "DomainMatrix([[EX(b - d), EX(-a + c), EX(a*d - b*c)]], (1, 3), EX)"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$to_sparse()$nullspace()",
      "DomainMatrix({0: {2: EX(a*d - b*c), 0: EX(b - d), 1: EX(-a + c)}}, (1, 3), EX)"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$rep$rref_den()",
      "(DDM([[EX(a*d - b*c), EX(0), EX(-b + d)], [EX(0), EX(a*d - b*c), EX(a - c)]], (2, 3), EX), EX(a*d - b*c), [0, 1])"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$to_sdm()$rref_den()",
      "(SDM({0: {2: EX(-b + d), 0: EX(a*d - b*c)}, 1: {2: EX(a - c), 1: EX(a*d - b*c)}}, (2, 3), EX), EX(a*d - b*c), [0, 1])"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$to_field()$to_sdm()$rref()",
      "(SDM({0: {0: EX(1), 2: EX(-b/(a*d - b*c) + d/(a*d - b*c))}, 1: {1: EX(1), 2: EX(a/(a*d - b*c) - c/(a*d - b*c))}}, (2, 3), EX), [0, 1])"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$to_field()$rep$rref()",
      "(DDM([[EX(1), EX(0), EX(-b/(a*d - b*c) + d/(a*d - b*c))], [EX(0), EX(1), EX(a/(a*d - b*c) - c/(a*d - b*c))]], (2, 3), EX), [0, 1])"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$transpose()",
      "DomainMatrix([[EX(a), EX(c)], [EX(b), EX(d)], [EX(1), EX(1)]], (3, 2), EX)"),
    c(".dmt(EX, list(list(\"a\", \"b\", \"1\"), list(\"c\", \"d\", \"1\")), c(2, 3))$to_Matrix()",
