})

test_that("DomainMatrix, DDM, SDM and normal forms match SymPy (part 10)", {
  pt_check(list(
    c(".dmt(ZZ, list(), c(0, 2))$to_Matrix()",
      "Matrix(0, 2, [])"),
    c(".dmt(ZZ, list(), c(0, 2))$nnz()",
      "0"),
    c(".dmt(ZZ, list(), c(0, 2))$fflu()",
      "(DomainMatrix([], (0, 0), ZZ), DomainMatrix([], (0, 0), ZZ), DomainMatrix([], (0, 0), ZZ), DomainMatrix([], (0, 2), ZZ))"),
    c(".dmt(ZZ, list(), c(0, 2)) * .dmt(ZZ, list(), c(0, 2))$transpose()",
      "DomainMatrix([], (0, 0), ZZ)"),
    c(".dmt(ZZ, list(), c(0, 2))$rref(method = 'CD')",
      "(DomainMatrix([], (0, 2), QQ), ())"),
    c(".dmt(ZZ, list(), c(0, 2))$rref_den(method = 'CD')",
      "(DomainMatrix([], (0, 2), ZZ), 1, ())"),
    c(".dmt(ZZ, list(), c(0, 2))$to_field()$nullspace(divide_last = TRUE)",
      "DomainMatrix([[1, 0], [0, 1]], (2, 2), QQ)"),
    c(".dmt(ZZ, list(), c(0, 2))$to_field()$columnspace()",
      "DomainMatrix([], (0, 0), QQ)"),
    c(".dmt(ZZ, list(), c(0, 2))$to_field()$rowspace()",
      "DomainMatrix([], (0, 2), QQ)"),
    c(".dmt(ZZ, list(), c(0, 2))$content()",
      "0"),
    c(".dmt(ZZ, list(), c(0, 2))$primitive()",
      "(0, DomainMatrix([], (0, 2), ZZ))"),
    c(".dmt(ZZ, list(), c(0, 2))$to_field()$clear_denoms()",
