})

test_that("DomainMatrix, DDM, SDM and normal forms match SymPy (part 11)", {
  pt_check(list(
    c(".dmt(ZZ, list(list(\"1\", \"1\")), c(1, 2))$to_field()$nullspace(divide_last = TRUE)",
      "DomainMatrix([[-1, 1]], (1, 2), QQ)"),
    c(".dmt(ZZ, list(list(\"1\", \"1\")), c(1, 2))$to_field()$columnspace()",
      "DomainMatrix([[1]], (1, 1), QQ)"),
    c(".dmt(ZZ, list(list(\"1\", \"1\")), c(1, 2))$to_field()$rowspace()",
      "DomainMatrix([[1, 1]], (1, 2), QQ)"),
    c(".dmt(ZZ, list(list(\"1\", \"1\")), c(1, 2))$content()",
      "1"),
    c(".dmt(ZZ, list(list(\"1\", \"1\")), c(1, 2))$primitive()",
      "(1, DomainMatrix([[1, 1]], (1, 2), ZZ))"),
    c(".dmt(ZZ, list(list(\"1\", \"1\")), c(1, 2))$to_field()$clear_denoms()",
      "(1, DomainMatrix([[1, 1]], (1, 2), QQ))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))",
      "DomainMatrix([[1, 2, 3], [4, 5, 6]], (2, 3), ZZ)"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$rref()",
      "(DomainMatrix([[1, 0, -1], [0, 1, 2]], (2, 3), QQ), (0, 1))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$rref_den()",
      "(DomainMatrix([[-3, 0, 3], [0, -3, -6]], (2, 3), ZZ), -3, (0, 1))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$to_sparse()$rref()",
      "(DomainMatrix({0: {2: -1, 0: 1}, 1: {2: 2, 1: 1}}, (2, 3), QQ), (0, 1))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$to_sparse()$rref_den()",
      "(DomainMatrix({0: {2: 3, 0: -3}, 1: {2: -6, 1: -3}}, (2, 3), ZZ), -3, (0, 1))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$rref(method = 'GJ')",
      "(DomainMatrix([[1, 0, -1], [0, 1, 2]], (2, 3), QQ), (0, 1))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$rref(method = 'FF')",
      "(DomainMatrix([[1, 0, -1], [0, 1, 2]], (2, 3), QQ), (0, 1))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$rref_den(method = 'GJ')",
      "(DomainMatrix([[1, 0, -1], [0, 1, 2]], (2, 3), ZZ), 1, (0, 1))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$rref_den(method = 'FF_dense')",
      "(DomainMatrix([[-3, 0, 3], [0, -3, -6]], (2, 3), ZZ), -3, (0, 1))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$rref(method = 'GJ_dense')",
      "(DomainMatrix([[1, 0, -1], [0, 1, 2]], (2, 3), QQ), (0, 1))"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$rank()",
      "2"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$nullspace()",
      "DomainMatrix([[3, -6, 3]], (1, 3), ZZ)"),
    c(".dmt(ZZ, list(list(\"1\", \"2\", \"3\"), list(\"4\", \"5\", \"6\")), c(2, 3))$to_sparse()$nullspace()",
      "DomainMatrix({0: {2: 3, 0: 3, 1: -6}}, (1, 3), ZZ)"),
