      "[1, 4]"),
    c("DM(list(list(1, 2, 3), list(4, 5, 6)), ZZ)$diagonal()",
      "[1, 5]"),
    c("DM(list(list(1, 2), list(3, 4), list(6, 8)), QQ)$rank()",
      "2"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) + DM(list(list(1, 2), list(3, 4)), ZZ)",
      "DomainMatrix([[2, 4], [6, 8]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$add(DM(list(list(1, 2), list(3, 4)), ZZ))",
      "DomainMatrix([[2, 4], [6, 8]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) + DM(list(list(1, 2)), ZZ)",
      "ERR DMShapeError: Shape mismatch: (2, 2) + (1, 2)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$add(DM(list(list(1, 2)), ZZ))",
      "ERR DMShapeError: Shape mismatch: (2, 2) + (1, 2)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) + DM(list(list(1, 2), list(3, 4)), QQ)",
      "DomainMatrix([[2, 4], [6, 8]], (2, 2), QQ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$add(DM(list(list(1, 2), list(3, 4)), QQ))",
      "ERR DMDomainError: Domain mismatch: ZZ + QQ"),
    c("DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ) + DM(list(list(1, 2), list(3, 4)), ZZ)",
      "DomainMatrix([[1, 3], [5, 4]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) + DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ)",
      "DomainMatrix([[1, 3], [5, 4]], (2, 2), ZZ)"),
    c("DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ)$add(DM(list(list(1, 2), list(3, 4)), ZZ))",
      "ERR DMFormatError: Format mismatch: sparse + dense"),
    c("DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ) + DomainMatrix(list(`1` = list(`1` = ZZ(5)), `0` = list(`1` = ZZ(-1))), c(2, 2), ZZ)",
      "DomainMatrix({1: {0: 2, 1: 5}}, (2, 2), ZZ)"),
    c("DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ)$add(DomainMatrix(list(`1` = list(`1` = ZZ(5)), `0` = list(`1` = ZZ(-1))), c(2, 2), ZZ))",
      "DomainMatrix({1: {0: 2, 1: 5}}, (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) - DM(list(list(1, 2), list(3, 4)), ZZ)",
      "DomainMatrix([[0, 0], [0, 0]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$to_sparse()$sub(DM(list(list(1, 2), list(3, 4)), ZZ)$to_sparse())",
      "DomainMatrix({}, (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) - DM(list(list(1, 2)), ZZ)",
      "ERR DMShapeError: Shape mismatch: (2, 2) - (1, 2)"),
    c("DM(list(list(1, 2), list(3, 4)), QQ) - DM(list(list(1, 2), list(3, 4)), ZZ)",
      "DomainMatrix([[0, 0], [0, 0]], (2, 2), QQ)"),
