      "ERR DMDomainError: Domain mismatch: QQ - ZZ"),
    c("DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ) - DM(list(list(1, 2), list(3, 4)), ZZ)",
      "DomainMatrix([[-1, -1], [-1, -4]], (2, 2), ZZ)"),
    c("-DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ)",
      "DomainMatrix({0: {1: -1}, 1: {0: -2}}, (2, 2), ZZ)"),
    c("-DM(list(list(1, 2), list(3, 4)), ZZ)",
      "DomainMatrix([[-1, -2], [-3, -4]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$neg()",
      "DomainMatrix([[-1, -2], [-3, -4]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) * DM(list(list(1, 2), list(3, 4)), ZZ)",
      "DomainMatrix([[7, 10], [15, 22]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$matmul(DM(list(list(1, 2), list(3, 4)), ZZ))",
      "DomainMatrix([[7, 10], [15, 22]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) * DM(list(list(1, 2), list(3, 4)), QQ)",
      "DomainMatrix([[7, 10], [15, 22]], (2, 2), QQ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$matmul(DM(list(list(1, 2), list(3, 4)), QQ))",
      "ERR DMDomainError: Domain mismatch: ZZ * QQ"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) * ZZ(2)",
      "DomainMatrix([[2, 4], [6, 8]], (2, 2), ZZ)"),
    c("ZZ(2) * DM(list(list(1, 2), list(3, 4)), ZZ)",
      "DomainMatrix([[2, 4], [6, 8]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$mul(ZZ(2))",
      "DomainMatrix([[2, 4], [6, 8]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) * ZZ(0)",
      "DomainMatrix({}, (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$mul(ZZ(0))",
      "DomainMatrix([[0, 0], [0, 0]], (2, 2), ZZ)"),
    c("DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ) * DM(list(list(1, 2), list(3, 4)), ZZ)",
      "DomainMatrix([[3, 4], [2, 4]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ) * DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ)",
      "DomainMatrix([[4, 1], [8, 3]], (2, 2), ZZ)"),
    c("DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ) * DomainMatrix(list(`0` = list(`1` = ZZ(1)), `1` = list(`0` = ZZ(2))), c(2, 2), ZZ)",
      "DomainMatrix({0: {0: 2}, 1: {1: 2}}, (2, 2), ZZ)"),
    c("DM(list(list(2, 2), list(0, 0)), ZZ)$mul_elementwise(DM(list(list(4, 0), list(3, 0)), ZZ))",
      "DomainMatrix([[8, 0], [0, 0]], (2, 2), ZZ)"),
    c("DM(list(list(2, 2), list(0, 0)), ZZ)$to_sparse()$mul_elementwise(DM(list(list(4, 0), list(3, 0)), ZZ)$to_sparse())",
      "DomainMatrix({0: {0: 8}}, (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)^0",
      "DomainMatrix({0: {0: 1}, 1: {1: 1}}, (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)^1",
      "DomainMatrix([[1, 2], [3, 4]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)^3",
      "DomainMatrix([[37, 54], [81, 118]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$pow(5)",
      "DomainMatrix([[1069, 1558], [2337, 3406]], (2, 2), ZZ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$pow(-1)",
      "ERR NotImplementedError: Negative powers"),
    c("DomainMatrix_zeros(c(2, 1), ZZ)^1",
      "ERR DMNonSquareMatrixError: Power of a nonsquare matrix"),
    c("DM(list(list(c(1, 2), c(1, 3)), list(c(1, 4), c(1, 5))), QQ)$clear_denoms()",
