    c("DM(list(list(c(1, 2), c(1, 3)), list(c(1, 4), c(1, 5))), QQ)$clear_denoms(convert = TRUE)",
      "(60, DomainMatrix([[30, 20], [15, 12]], (2, 2), ZZ))"),
    c("DM(list(list(c(1, 2), c(1, 3)), list(c(1, 4), c(1, 5))), QQ) * DomainScalar(ZZ(60), ZZ)",
      "DomainMatrix([[30, 20], [15, 12]], (2, 2), QQ)"),
    c("DM(list(list(30, 20), list(15, 12)), QQ) / DomainScalar(ZZ(60), ZZ)",
      "DomainMatrix([[1/2, 1/3], [1/4, 1/5]], (2, 2), QQ)"),
    c("DM(list(list(30, 20), list(15, 12)), ZZ) / 4",
      "DomainMatrix([[15/2, 5], [15/4, 3]], (2, 2), QQ)"),
    c("DM(list(list(c(1, 2), c(1, 3)), list(c(1, 4), c(1, 5))), QQ)$clear_denoms_rowwise()",
      "(DomainMatrix({0: {0: 6}, 1: {1: 20}}, (2, 2), ZZ), DomainMatrix([[3, 2], [5, 4]], (2, 2), QQ))"),
    c("DM(list(list(c(1, 2), c(1, 3)), list(c(1, 4), c(1, 5))), QQ)$clear_denoms_rowwise(convert = TRUE)",
      "(DomainMatrix({0: {0: 6}, 1: {1: 20}}, (2, 2), ZZ), DomainMatrix([[3, 2], [5, 4]], (2, 2), ZZ))"),
    c("DM(list(list(c(1, 2), c(1, 3), 0, 0), list(0, 0, 0, 0), list(c(1, 4), c(1, 5), c(1, 6), c(1, 7))), QQ)$clear_denoms_rowwise()",
      "(DomainMatrix({0: {0: 6}, 1: {1: 1}, 2: {2: 420}}, (3, 3), ZZ), DomainMatrix([[3, 2, 0, 0], [0, 0, 0, 0], [105, 84, 70, 60]], (3, 4), QQ))"),
    c("DM(list(list(c(1, 2), c(1, 3), 0, 0), list(0, 0, 0, 0), list(c(1, 4), c(1, 5), c(1, 6), c(1, 7))), QQ)$clear_denoms_rowwise(convert = TRUE)",
      "(DomainMatrix({0: {0: 6}, 1: {1: 1}, 2: {2: 420}}, (3, 3), ZZ), DomainMatrix([[3, 2, 0, 0], [0, 0, 0, 0], [105, 84, 70, 60]], (3, 4), ZZ))"),
    c("DM(list(list(2, 4), list(6, 8)), ZZ)$cancel_denom(ZZ(1))",
      "(DomainMatrix([[2, 4], [6, 8]], (2, 2), ZZ), 1)"),
    c("DM(list(list(2, 4), list(6, 8)), ZZ)$cancel_denom(ZZ(3))",
      "(DomainMatrix([[2, 4], [6, 8]], (2, 2), ZZ), 3)"),
    c("DM(list(list(2, 4), list(6, 8)), ZZ)$cancel_denom(ZZ(4))",
      "(DomainMatrix([[1, 2], [3, 4]], (2, 2), ZZ), 2)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$cancel_denom(ZZ(2))",
      "(DomainMatrix([[1, 2], [3, 4]], (2, 2), ZZ), 2)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$cancel_denom(ZZ(-2))",
      "(DomainMatrix([[-1, -2], [-3, -4]], (2, 2), ZZ), 2)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$cancel_denom(ZZ(0))",
      "ERR ZeroDivisionError: denominator is zero"),
    c("DM(list(list(2, 4), list(6, 8)), ZZ)$cancel_denom_elementwise(ZZ(1))",
      "(DomainMatrix([[2, 4], [6, 8]], (2, 2), ZZ), DomainMatrix([[1, 1], [1, 1]], (2, 2), ZZ))"),
    c("DM(list(list(2, 4), list(6, 8)), ZZ)$cancel_denom_elementwise(ZZ(4))",
      "(DomainMatrix([[1, 1], [3, 2]], (2, 2), ZZ), DomainMatrix([[2, 1], [2, 1]], (2, 2), ZZ))"),
    c("DM(list(list(2, 4), list(6, 8)), ZZ)$cancel_denom_elementwise(ZZ(0))",
      "ERR ZeroDivisionError: denominator is zero"),
    c("DM(list(list(2, 4), list(6, 8)), ZZ)$content()",
      "2"),
    c("DM(list(list(2, 4), list(6, 8)), ZZ)$primitive()",
      "(2, DomainMatrix([[1, 2], [3, 4]], (2, 2), ZZ))"),
    c("DM(list(list(1, 2, 3), list(0, 1, 0), list(2, 0, 4)), ZZ)$scc()",
      "[[1], [0, 2]]"),
    c("DM(list(list(1, 2, 3), list(0, 1, 0), list(2, 0, 4)), ZZ)$to_sparse()$scc()",
      "[[1], [0, 2]]"),
    c("DM(list(list(1, 2, 3)), ZZ)$scc()",
      "ERR DMNonSquareMatrixError: Matrix must be square for scc"),
    c("DomainMatrix(list(), c(0, 1), QQ)$rref()",
      "(DomainMatrix([], (0, 1), QQ), ())"),
    c("DomainMatrix(list(list(QQ(1))), c(1, 1), QQ)$rref()",
      "(DomainMatrix([[1]], (1, 1), QQ), (0,))"),
    c("DomainMatrix(list(list(QQ(0))), c(1, 1), QQ)$rref()",
      "(DomainMatrix([[0]], (1, 1), QQ), ())"),
    c("DM(list(list(0, 2), list(3, 4)), QQ)$rref()",
      "(DomainMatrix([[1, 0], [0, 1]], (2, 2), QQ), (0, 1))"),
    c("DM(list(list(0, 2), list(0, 4)), QQ)$rref()",
      "(DomainMatrix([[0, 1], [0, 0]], (2, 2), QQ), (1,))"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$rref(method = \"CD_dense\")",
      "(DomainMatrix([[1, 0], [0, 1]], (2, 2), QQ), (0, 1))"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$rref(method = \"FF_dense\")",
      "(DomainMatrix([[1, 0], [0, 1]], (2, 2), QQ), (0, 1))"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$rref(method = \"foo\")",
      "ERR ValueError: Unknown method for rref: foo"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$rref_den(method = \"foo\")",
      "ERR ValueError: Unknown method for rref: foo"),
    c("DM(list(list(1, -1, 1), list(2, -2, 3)), QQ)$columnspace()",
      "DomainMatrix([[1, 1], [2, 3]], (2, 2), QQ)"),
    c("DM(list(list(1, -1, 1), list(2, -2, 3)), ZZ)$columnspace()",
      "ERR DMNotAField: Not a field"),
    c("DM(list(list(1, -1, 1), list(2, -2, 3)), QQ)$to_sparse()$columnspace()",
      "DomainMatrix({0: {0: 1, 1: 1}, 1: {0: 2, 1: 3}}, (2, 2), QQ)"),
    c("DM(list(list(1, -1, 1), list(2, -2, 3)), QQ)$rowspace()",
      "DomainMatrix([[1, -1, 1], [2, -2, 3]], (2, 3), QQ)"),
    c("DM(list(list(1, -1, 1), list(2, -2, 3)), ZZ)$rowspace()",
      "ERR DMNotAField: Not a field"),
    c("DM(list(list(1, 1), list(1, 1)), QQ)$nullspace()",
      "DomainMatrix([[-1, 1]], (1, 2), QQ)"),
    c("DM(list(list(1, 1), list(1, 1)), ZZ)$nullspace()",
      "DomainMatrix([[-1, 1]], (1, 2), ZZ)"),
    c("DM(list(list(1, 1), list(1, 1)), ZZ)$nullspace(divide_last = TRUE)",
      "ERR DMNotAField: Cannot normalize vectors over a non-field"),
    c("DM(list(list(2, 2), list(2, 2)), ZZ)$rref_den()",
      "(DomainMatrix([[2, 2], [0, 0]], (2, 2), ZZ), 2, (0,))"),
    c("DM(list(list(2, 2), list(0, 0)), ZZ)$nullspace_from_rref()",
      "DomainMatrix([[-2, 2]], (1, 2), ZZ)"),
    c("DM(list(list(2, 2), list(0, 0)), ZZ)$to_sparse()$nullspace_from_rref()",
      "DomainMatrix({0: {1: 2, 0: -2}}, (1, 2), ZZ)"),
    c("DM(list(list(2, 2), list(0, 0)), ZZ)$to_sparse()$nullspace_from_rref(list(0))",
      "DomainMatrix({0: {1: 2, 0: -2}}, (1, 2), ZZ)"),
    c("DomainMatrix(list(), c(0, 0), QQ)$inv()",
      "DomainMatrix([], (0, 0), QQ)"),
    c("DM(list(list(1, 2), list(3, 4)), QQ)$inv()",
      "DomainMatrix([[-2, 1], [3/2, -1/2]], (2, 2), QQ)"),
    c("DM(list(list(1, 2), list(3, 4)), ZZ)$inv()",
      "ERR DMNotAField: Not a field"),
    c("DM(list(list(1, 2)), QQ)$inv()",
      "ERR DMNonSquareMatrixError: "),
    c("DM(list(list(1, 2), list(3, 6)), QQ)$inv()",
      "ERR DMNonInvertibleMatrixError: Matrix det == 0; not invertible."),
    c("DM(list(list(1, 2), list(3, 4)), FF(3))$inv()",
      "DomainMatrix([[1 mod 3, 1 mod 3], [0 mod 3, 1 mod 3]], (2, 2), GF(3))"),
    c("DM(list(list(1, 2), list(3, 4)), FF(7))$det()",
      "5 mod 7"),
    c("DM(list(list(1, 2), list(3, 4)), FF(7))$rref()",
      "(DomainMatrix([[1 mod 7, 0 mod 7], [0 mod 7, 1 mod 7]], (2, 2), GF(7)), (0, 1))"),
    c("DM(list(list(1, 2), list(3, 4)), FF(7))$charpoly()",
      "[SymmetricModularIntegerMod7(1), SymmetricModularIntegerMod7(2), SymmetricModularIntegerMod7(5)]"),
    c("DM(list(list(1, 2), list(3, 4)), FF(7))$to_sparse()$inv()",
      "DomainMatrix({0: {0: 5 mod 7, 1: 1 mod 7}, 1: {0: 5 mod 7, 1: 3 mod 7}}, (2, 2), GF(7))")
  ))
})

test_that("fraction fields, rings and cancel match SymPy (part 1)", {
  pt_check(list(
    c(".withF(\"x,y\", QQ, function(F, x, y) -((7*x - 9)/y))",
      "(-7*x + 9)/y"),
    c(".withF(\"x,y\", QQ, function(F, x, y) 1/x + 1/y)",
      "(x + y)/(x*y)"),
    c(".withF(\"x,y\", QQ, function(F, x, y) 1/y + 1/x)",
      "(x + y)/(x*y)"),
    c(".withF(\"x,y\", QQ, function(F, x, y) (1/x + 1/y) == (x + y)/(x*y))",
      "True"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) x + 3)",
      "x + 3"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) 3 + x)",
      "x + 3"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) x + Rational(3, 7))",
      "(7*x + 3)/7"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) Rational(3, 7) + x)",
      "(7*x + 3)/7"),
    c(".withF(\"x,y\", QQ, function(F, x, y) 1/x - 1/y)",
      "(-x + y)/(x*y)"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) x - 3)",
      "x - 3"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) -(3 - x))",
      "x - 3"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) x - Rational(3, 7))",
      "(7*x - 3)/7"),
    c(".withF(\"x,y\", QQ, function(F, x, y) (1/x)*(1/y))",
      "1/(x*y)"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) x*3)",
      "3*x"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) x*Rational(3, 7))",
      "3*x/7"),
    c(".withF(\"x,y\", QQ, function(F, x, y) (1/x)/(1/y))",
      "y/x"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) x/Rational(3, 7))",
      "7*x/3"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) (Rational(3, 7)/x)^-1)",
      "7*x/3"),
    c(".withF(\"x,y\", ZZ, function(F, x, y) x/0)",
      "ERR ZeroDivisionError: "),
    c(".withF(\"x,y\", ZZ, function(F, x, y) 1/(x - x))",
      "ERR ZeroDivisionError: "),
    c(".withF(\"x,y\", ZZ, function(F, x, y) x/(x - x))",
      "ERR ZeroDivisionError: "),
    c(".withF(\"x,y\", QQ, function(F, x, y) (1/x)^3)",
      "1/(x^3)"),
    c(".withF(\"x,y\", QQ, function(F, x, y) (1/x*1/y)^3)",
      "1/(x^3*y^3)"),
    c(".withF(\"x,y\", QQ, function(F, x, y) (1/x*1/y)^-3)",
      "x^3*y^3"),
    c(".withF(\"x,y\", QQ, function(F, x, y) (x - x)^-3)",
      "ERR ZeroDivisionError: "),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) (3*x^2*y - x*y*z)/(7*z^3 + 1))",
      "(3*x^2*y - x*y*z)/(7*z^3 + 1)"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) (x*y*z + x*y + x)/(x*y + 7))",
      "(x*y*z + x*y + x)/(x*y + 7)"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) (x^2 - y^2)/(x - y))",
      "x + y"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) (x^2 + 3*y)/z)",
      "(x^2 + 3*y)/z"),
    c(".withF(\"x,y,z\", QQ, function(F, x, y, z) (x^2/2 + 3*y)/(z/3))",
      "(3*x^2 + 18*y)/(2*z)"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) (x^3 - 1)/(x^2 - 1))",
      "(x^2 + x + 1)/(x + 1)"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) (2*x - 2)/(4*x^2 - 4))",
      "1/(2*x + 2)"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) (-x - 1)/(1 - x))",
      "(x + 1)/(x - 1)"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) (x + y)^2/(x*z))",
      "(x^2 + 2*x*y + y^2)/(x*z)"),
    c(".withF(\"x,y,z\", QQ, function(F, x, y, z) x/2 + y/3)",
      "(3*x + 2*y)/6"),
    c(".withF(\"x,y,z\", QQ, function(F, x, y, z) (x + 1)/(2*y + 4))",
      "(x + 1)/(2*y + 4)"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) x == x)",
      "True"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) x == y)",
      "False"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) (x - y)/(y - x))",
      "-1"),
    c(".withF(\"x,y,z\", ZZ, function(F, x, y, z) 1/(x*y) - 1/(x*z))",
      "(-y + z)/(x*y*z)"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) (x + y)^2)",
      "x^2 + 2*x*y + y^2"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) x*y - y*x)",
      "0"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) x^2 - y^2)",
      "x^2 - y^2"),
    c(".withR(\"x,y\", QQ, function(R, x, y) x/2 + y)",
      "1/2*x + y"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) (x^2 - y^2)/(x - y))",
      "x + y"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) x/y)",
      "ERR ExactQuotientFailed: y does not divide x"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) x + 1)",
      "x + 1"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) -x - 3*y + 7)",
      "-x - 3*y + 7"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) (x - y)^3)",
      "x^3 - 3*x^2*y + 3*x*y^2 - y^3"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) 3*x^2*y - x*y + 1)",
      "3*x^2*y - x*y + 1"),
    c(".withR(\"x,y\", QQ, function(R, x, y) (x + y)^2/4)",
      "1/4*x^2 + 1/2*x*y + 1/4*y^2"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) x == x)",
      "True"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) x != y)",
      "True"),
    c(".withR(\"x,y\", ZZ, function(R, x, y) x*(x + 1) == x^2 + x)",
      "True"),
    c(".withR(\"x,y,z\", ZZ, function(R, x, y, z) (x*y + z)*(x - z))",
      "x^2*y - x*y*z + x*z - z^2"),
    c(".withR(\"x,y,z\", ZZ, function(R, x, y, z) (x + y + z)^3)",
      "x^3 + 3*x^2*y + 3*x^2*z + 3*x*y^2 + 6*x*y*z + 3*x*z^2 + y^3 + 3*y^2*z + 3*y*z^2 + z^3"),
    c(".withR(\"x,y,z\", ZZ, function(R, x, y, z) (x^2 + 2*x*y)/x)",
      "x + 2*y"),
    c(".withR(\"x,y,z\", ZZ, function(R, x, y, z) -(x - y))",
      "-x + y"),
    c(".withR(\"x,y,z\", ZZ, function(R, x, y, z) x^0)",
      "1"),
    c(".withR(\"x,y,z\", ZZ, function(R, x, y, z) x - x)",
      "0"),
    c("cancel(0)",
      "0"),
    c("cancel(7)",
      "7"),
    c("cancel(x)",
      "x"),
    c("cancel(oo)",
      "oo"),
    c("cancel(list(1, 2, 3))",
      "ERR ValueError: unexpected argument: (1, 2, 3)"),
    c("cancel(list(2, 3))",
      "(1, 2, 3)"),
    c("cancel(list(1, 0), x)",
      "(1, 1, 0)"),
    c("cancel(list(0, 1), x)",
      "(1, 0, 1)"),
    c("Poly(4*x^2 - 4, x)$cancel(Poly(2*x - 2, x))",
      "(1, Poly(2*x + 2, x, domain='ZZ'), Poly(1, x, domain='ZZ'))"),
    c("cancel(list(4*x^2 - 4, 2*x - 2))",
      "(1, 2*x + 2, 1)"),
    c("cancel(list(4*x^2 - 4, 2*x - 2), x)",
      "(1, 2*x + 2, 1)"),
    c("cancel(list(Poly(4*x^2 - 4, x), Poly(2*x - 2, x)))",
      "(1, Poly(2*x + 2, x, domain='ZZ'), Poly(1, x, domain='ZZ'))"),
    c("cancel(list(4*x^2 - 4, 2*x - 2), polys = TRUE)",
      "(1, Poly(2*x + 2, x, domain='ZZ'), Poly(1, x, domain='ZZ'))"),
    c("cancel(list(Poly(4*x^2 - 4, x), Poly(2*x - 2, x)), polys = FALSE)",
      "(1, 2*x + 2, 1)"),
    c("cancel((x^2 - 2)/(x + sqrt(Integer(2))))",
      "(x^2 - 2)/(x + sqrt(2))"),
    c("cancel((x^2 - 2)/(x + sqrt(Integer(2))), greedy = FALSE)",
      "x - sqrt(2)"),
    c("cancel((x^2 - 2)/(x - sqrt(Integer(2))), greedy = FALSE)",
      "x + sqrt(2)"),
    c("cancel(list(x^2/4 - 1, x/2 - 1))",
      "(1, x + 2, 2)"),
    c("cancel((x^2 - y)/(x - y))",
      "(x^2 - y)/(x - y)"),
    c("cancel((x^2 - y^2)/(x - y), x)",
      "x + y"),
    c("cancel((x^2 - y^2)/(x - y), y)",
      "x + y"),
    c("cancel((x^2 - y^2)/(x - y))",
      "x + y"),
    c("cancel((x^3 - 1)/(x^2 - 1))",
      "(x^2 + x + 1)/(x + 1)"),
    c("cancel((x^3/2 - Rational(1, 2))/(x^2 - 1))",
      "(x^2 + x + 1)/(2*x + 2)"),
    c("cancel((exp(2*x) + 2*exp(x) + 1)/(exp(x) + 1))",
      "exp(x) + 1"),
    c("cancel(list(Poly(x^2 - a^2, x), Poly(x - a, x)))",
      "(1, Poly(x + a, x, domain='ZZ[a]'), Poly(1, x, domain='ZZ[a]'))"),
    c("cancel(list(x^3 + (sqrt(Integer(2)) - 2)*x^2 - (2*sqrt(Integer(2)) + 3)*x - 3*sqrt(Integer(2)), x^2 - 2), extension = TRUE)",
      "(1, x^2 - 2*x - 3, x - sqrt(2))"),
    c("cancel(list(Poly(-2*x + 3, x), Poly(-x^9 + x^8 + x^6 - x^5 + 2*x^2 - 3*x + 1, x)))",
      "(1, Poly(2*x - 3, x, domain='ZZ'), Poly(x^9 - x^8 - x^6 + x^5 - 2*x^2 + 3*x - 1, x, domain='ZZ'))"),
    c("Poly(x/3 + 1, x)$cancel(Poly(x/7 + 1, x))",
      "(7/3, Poly(x + 3, x, domain='QQ'), Poly(x + 7, x, domain='QQ'))"),
    c("Poly(x/3 + 1, x)$cancel(Poly(x/7 + 1, x), include = TRUE)",
      "(Poly(7*x + 21, x, domain='QQ'), Poly(3*x + 21, x, domain='QQ'))"),
    c("Poly(y, y, domain = 'ZZ(x)')$cancel(Poly(1, y, domain = 'ZZ[x]'))",
      "(1, Poly(y, y, domain='ZZ(x)'), Poly(1, y, domain='ZZ(x)'))"),
    c("Poly(y, y, domain = 'ZZ(x)')$cancel(Poly(1, y, domain = 'ZZ[x]'), include = TRUE)",
      "(Poly(y, y, domain='ZZ(x)'), Poly(1, y, domain='ZZ(x)'))"),
    c("Poly(5*x*y + x, y, domain = 'ZZ(x)')$cancel(Poly(2*x^2*y, y, domain = 'ZZ(x)'), include = TRUE)",
      "(Poly(5*y + 1, y, domain='ZZ(x)'), Poly(2*x*y, y, domain='ZZ(x)'))"),
    c("Poly(5*x*y + x, y, domain = 'ZZ(x)')$cancel(Poly(2*x^2*y, y, domain = 'ZZ(x)'))",
      "(1, Poly(5*y + 1, y, domain='ZZ(x)'), Poly(2*x*y, y, domain='ZZ(x)'))"),
    c("cancel((x^2 - 1)/(x + 1), modulus = 2)",
      "x + 1"),
    c("Poly(x^2 - 1, modulus = 2)$cancel(Poly(x + 1, modulus = 2))",
      "(1, Poly(x + 1, x, modulus=2), Poly(1, x, modulus=2))"),
    c("Poly(1 + x, x)$cancel(Poly(1 - x, x))",
      "(-1, Poly(x + 1, x, domain='ZZ'), Poly(x - 1, x, domain='ZZ'))"),
    c("Poly(1 - x, x)$cancel(Poly(1 + x, x))",
      "(-1, Poly(x - 1, x, domain='ZZ'), Poly(x + 1, x, domain='ZZ'))"),
    c("Poly(1 - x, x)$cancel(Poly(1 - x, x))",
      "(1, Poly(1, x, domain='ZZ'), Poly(1, x, domain='ZZ'))"),
    c("cancel(list(1 + x, 1 - x))",
      "(1, -x - 1, x - 1)"),
    c("cancel(list(1 - x, 1 + x))",
      "(1, 1 - x, x + 1)"),
    c("Poly(x*y - y, x, y)$cancel(Poly(y*x^2 - y, x, y))",
      "(1, Poly(1, x, y, domain='ZZ'), Poly(x + 1, x, y, domain='ZZ'))"),
    c("Poly(x^2 - a^2, x)$cancel(Poly(x - a, x))",
      "(1, Poly(x + a, x, domain='ZZ[a]'), Poly(1, x, domain='ZZ[a]'))"),
    c("Poly(x^2/a - a, x)$cancel(Poly(x/a - 1, x))",
      "(1, Poly(x + a, x, domain='ZZ(a)'), Poly(1, x, domain='ZZ(a)'))"),
    c("Poly(x^2 - a^2, x, domain = 'ZZ(a)')$cancel(Poly(x - a, x, domain = 'ZZ(a)'))",
      "(1, Poly(x + a, x, domain='ZZ(a)'), Poly(1, x, domain='ZZ(a)'))"),
    c("Poly(2*x/a + 2, x, domain = 'ZZ(a)')$cancel(Poly(4*x + 4*a, x, domain = 'ZZ(a)'))",
      "(1/a, Poly(1, x, domain='ZZ(a)'), Poly(2, x, domain='ZZ(a)'))"),
    c("Poly(x/(a + 1) + 1, x)$cancel(Poly(x + a + 1, x))",
      "(1/(a + 1), Poly(1, x, domain='ZZ(a)'), Poly(1, x, domain='ZZ(a)'))"),
    c("Poly(x/(a + 1) + 1, x)",
      "Poly(1/(a + 1)*x + 1, x, domain='ZZ(a)')"),
    c("Poly(x/(a + 1) + 1, x)$domain",
      "ZZ(a)"),
    c("cancel((x/(a + 1) + 1)/(x + a + 1))",
      "1/(a + 1)")
  ))
})

test_that("power series rings match SymPy (part 1)", {
  pt_check(list(
    c("local({R <- PythonPowerSeriesRingZZ(); R$equal(R(c(1, 2, 3)), R(c(1, 2, 3)))})",
      "True"),
    c("local({R <- PythonPowerSeriesRingQQ(); R$equal(R(c(1, 2, 3)), R(c(1, 2, 3)))})",
      "True"),
    c("local({R <- PythonPowerSeriesRingZZ(); R$equal(R(c(1, 21, 3)), R(c(1, 2, 3)))})",
      "False"),
    c("local({R <- PythonPowerSeriesRingQQ(); R$equal(R(c(1, 21, 3)), R(c(1, 2, 3)))})",
      "False"),
    c("local({R <- PythonPowerSeriesRingZZ(); R$equal(R(c(1, 2, 3), 3), R(c(1, 2, 3), 3))})",
      "None"),
    c("local({R <- PythonPowerSeriesRingQQ(); R$equal(R(c(1, 2, 3), 3), R(c(1, 2, 3), 3))})",
      "None"),
    c("local({R <- PythonPowerSeriesRingZZ(); R$equal(R(c(1, 2, 13), 3), R(c(1, 2, 3), 3))})",
      "False"),
    c("local({R <- PythonPowerSeriesRingQQ(); R$equal(R(c(1, 2, 13), 3), R(c(1, 2, 3), 3))})",
      "False"),
    c("local({R <- PythonPowerSeriesRingZZ(); R$equal(R(c(1, 2, 3), 3), R(c(1, 2, 3), 10))})",
      "None"),
    c("local({R <- PythonPowerSeriesRingQQ(); R$equal(R(c(1, 2, 3), 3), R(c(1, 2, 3), 10))})",
      "None"),
    c("local({R <- PythonPowerSeriesRingZZ(); R$equal(R(c(1, 21, 3), 3), R(c(1, 2, 3), 10))})",
      "False"),
