test_that("power series rings match SymPy (part 3)", {
  pt_check(list(
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R3$differentiate(R$pow_int(R3$add(R3$gen, R3$one), 4))})",
      "([MPQ(12,1), MPQ(12,1), MPQ(4,1)], 3)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R3(c(4, 12, 12), 3)})",
      "([MPQ(12,1), MPQ(12,1), MPQ(4,1)], 3)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R10(list(c(0, 1), c(0, 1), c(0, 1), c(4, 1)), NULL)})",
      "([MPQ(4,1), MPQ(0,1), MPQ(0,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R10(list(c(1, 1), c(2, 1)), NULL)})",
      "([MPQ(2,1), MPQ(1,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R$integrate(R$add(R$gen, R$one))})",
      "([MPQ(1,2), MPQ(1,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R(list(c(0, 1), c(1, 1), c(1, 2)), NULL)})",
      "([MPQ(1,2), MPQ(1,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R$integrate(R$multiply(R$gen, R$gen))})",
      "([MPQ(1,3), MPQ(0,1), MPQ(0,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R(list(c(0, 1), c(0, 1), c(0, 1), c(1, 3)), NULL)})",
      "([MPQ(1,3), MPQ(0,1), MPQ(0,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R3$integrate(R3$add(R3$gen, R3$one))})",
      "([MPQ(1,2), MPQ(1,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R3(list(c(0, 1), c(1, 1), c(1, 2)), NULL)})",
      "([MPQ(1,2), MPQ(1,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R3$integrate(R3$multiply(R3$gen, R3$gen))})",
      "([], 3)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R3(list(c(0, 1), c(0, 1), c(0, 1), c(1, 3)), NULL)})",
      "([], 3)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R3$integrate(R(c(2, 4, 1, 1), 5))})",
      "([MPQ(2,1), MPQ(2,1), MPQ(0,1)], 3)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R3(c(0, 2, 2), 3)})",
      "([MPQ(2,1), MPQ(2,1), MPQ(0,1)], 3)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R10$integrate(R10$add(R10$gen, R10$one))})",
      "([MPQ(1,2), MPQ(1,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R10(list(c(0, 1), c(1, 1), c(1, 2)), NULL)})",
      "([MPQ(1,2), MPQ(1,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R10$integrate(R10$pow_int(R10$gen, 2))})",
      "([MPQ(1,3), MPQ(0,1), MPQ(0,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R10(list(c(0, 1), c(0, 1), c(0, 1), c(1, 3)), NULL)})",
      "([MPQ(1,3), MPQ(0,1), MPQ(0,1), MPQ(0,1)], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R10$integrate(R10(c(2, 3, 4), 3))})",
      "([MPQ(4,3), MPQ(3,2), MPQ(2,1), MPQ(0,1)], 4)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R10(list(c(0, 1), c(2, 1), c(3, 2), c(4, 3)), 4)})",
      "([MPQ(4,3), MPQ(3,2), MPQ(2,1), MPQ(0,1)], 4)"),
    c("local({R <- PythonPowerSeriesRingZZ(); R$pow_int(R$gen, -1)})",
      "ERR ValueError: Result would not be a power series"),
    c("local({R <- PythonPowerSeriesRingQQ(); R$pow_int(R$gen, -1)})",
      "ERR ValueError: Result would not be a power series"),
    c("local({R <- PythonPowerSeriesRingZZ(); R$truncate(R$gen, -1)})",
      "ERR ValueError: Truncation precision must be non-negative"),
    c("local({R <- PythonPowerSeriesRingQQ(); R$truncate(R$gen, -1)})",
      "ERR ValueError: Truncation precision must be non-negative"),
    c("local({R <- PythonPowerSeriesRingZZ(); R3 <- PythonPowerSeriesRingZZ(3); R10 <- PythonPowerSeriesRingZZ(10); R$compose(R(c(2)), R(c(0, 1, 1)))})",
      "([2], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R$compose(R(c(2)), R(c(0, 1, 1)))})",
      "([MPQ(2,1)], None)"),
    c("local({R <- PythonPowerSeriesRingZZ(); R3 <- PythonPowerSeriesRingZZ(3); R10 <- PythonPowerSeriesRingZZ(10); R(c(2), NULL)})",
      "([2], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R(c(2), NULL)})",
      "([MPQ(2,1)], None)"),
    c("local({R <- PythonPowerSeriesRingZZ(); R3 <- PythonPowerSeriesRingZZ(3); R10 <- PythonPowerSeriesRingZZ(10); R$compose(R$add(R$one, R$gen), R$gen)})",
      "([1, 1], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R$compose(R$add(R$one, R$gen), R$gen)})",
      "([MPQ(1,1), MPQ(1,1)], None)"),
