      "([1, 0, 1, 0, 1], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R$compose(R(c(1, 1, 1)), R$square(R$gen))})",
      "([MPQ(1,1), MPQ(0,1), MPQ(1,1), MPQ(0,1), MPQ(1,1)], None)"),
    c("local({R <- PythonPowerSeriesRingZZ(); R3 <- PythonPowerSeriesRingZZ(3); R10 <- PythonPowerSeriesRingZZ(10); R(c(1, 0, 1, 0, 1), NULL)})",
      "([1, 0, 1, 0, 1], None)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R(c(1, 0, 1, 0, 1), NULL)})",
      "([MPQ(1,1), MPQ(0,1), MPQ(1,1), MPQ(0,1), MPQ(1,1)], None)"),
    c("local({R <- PythonPowerSeriesRingZZ(); R3 <- PythonPowerSeriesRingZZ(3); R10 <- PythonPowerSeriesRingZZ(10); R3$compose(R3(c(1, 2, 3)), R3(c(0, 1, 1)))})",
      "([5, 2, 1], 3)"),
    c("local({R <- PythonPowerSeriesRingQQ(); R3 <- PythonPowerSeriesRingQQ(3); R10 <- PythonPowerSeriesRingQQ(10); R3$compose(R3(c(1, 2, 3)), R3(c(0, 1, 1)))})",
      "([MPQ(5,1), MPQ(2,1), MPQ(1,1)], 3)"),
