test_that("Poly domains, gcd, sqf_part, interpolation, PurePoly, groebner order, all_roots and exquo match SymPy (part 1)", {
  pt_check(list(
    c("Poly(x^2 + 1, x, domain = \"QQ\")",
      "Poly(x^2 + 1, x, domain='QQ')"),
    c("Poly(x^2 + 1, x, domain = QQ)",
      "Poly(x^2 + 1, x, domain='QQ')"),
    c("Poly(x^2 + 1, x, domain = \"QQ\")$domain",
      "QQ"),
    c("Poly(x^2/2 + 1, x, domain = \"QQ\")",
      "Poly(1/2*x^2 + 1, x, domain='QQ')"),
    c("Poly(2*x*y + 4, x, y, domain = \"QQ\")",
      "Poly(2*x*y + 4, x, y, domain='QQ')"),
    c("Poly(x^2 + 1, x, domain = \"ZZ\")",
      "Poly(x^2 + 1, x, domain='ZZ')"),
    c("gcd(Poly(x^2 + 1, x, modulus = 2), Poly(x + 1, x, modulus = 2))",
      "Poly(x + 1, x, modulus=2)"),
    c("gcd(Poly(x^3 + 1, x, modulus = 3), Poly(x^2 + 2*x + 1, x, modulus = 3))",
      "Poly(x^2 - x + 1, x, modulus=3)"),
    c("gcd(Poly(x^2 - 1, x, modulus = 5), Poly(x^2 + 3*x + 2, x, modulus = 5))",
      "Poly(x + 1, x, modulus=5)"),
    c("gcd(x^2 + 1, x + 1, modulus = 2)",
      "x + 1"),
    c("sqf_part(x^3 - 3*x - 2)",
      "x^2 - x - 2"),
    c("sqf_part(Poly(x^3 - 3*x - 2))",
      "Poly(x^2 - x - 2, x, domain='ZZ')"),
    c("sqf_part((x - 1)^2*(x + 2))",
      "x^2 + x - 2"),
    c("sqf_part(2*x^2 + 4*x + 2)",
      "x + 1"),
    c("sqf_part(-x^3 + 3*x + 2)",
      "x^2 - x - 2"),
    c("sqf_part(x^4 - x^2, modulus = 3)",
      "x^3 - x"),
    c("sqf_part(Poly(x^3 + x, x, modulus = 3))",
      "Poly(x^3 + x, x, modulus=3)"),
    c("sqf_part(x^2*y^2 + 2*x*y^2 + y^2)",
      "x*y + y"),
