test_that("integrate keeps exp(1/2) and E independent", {
  x <- Symbol("x")
  expect_identical(sstr(integrate(1/(1 + exp(x - Rational(1, 2))/(1 + exp(x))), x)),
                   "x - exp(1/2)*log(exp(x) + exp(1/2)/(1 + exp(1/2)))/(exp(1/2) + E)")
})
